import{_ as a,o as t,c as n,a5 as s}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Scheduled chat messages","description":"","frontmatter":{},"headers":[],"relativePath":"feature/chat-scheduled-messages/spec.md","filePath":"feature/chat-scheduled-messages/spec.md"}'),i={name:"feature/chat-scheduled-messages/spec.md"};function o(r,e,c,d,l,h){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="scheduled-chat-messages" tabindex="-1">Scheduled chat messages <a class="header-anchor" href="#scheduled-chat-messages" aria-label="Permalink to &quot;Scheduled chat messages&quot;">​</a></h1><h2 id="objective-and-scope" tabindex="-1">Objective and scope <a class="header-anchor" href="#objective-and-scope" aria-label="Permalink to &quot;Objective and scope&quot;">​</a></h2><p>Workspace members can schedule a rich-text message in a DM, channel or thread (confirmed 2026-10-26). Keep existing channel/context permissions, mentions, notifications, unread tracking and immediate-send behavior. No uploads, recurring messages or edits to scheduled content in this iteration; pending content can be cancelled and composed again. Users can change the send time or cancel a pending or failed item. No automatic migration/seed on shared databases.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>A split Send control opens tomorrow 09:00, next Monday 09:00 and custom date/time. Enter still sends immediately; scheduling requires an explicit action.</li><li>Dates use the browser&#39;s IANA time zone, displayed before confirmation, and are stored as UTC Instants plus the original zone. Technical bounds: at least 60 seconds ahead and at most 120 days at creation/reschedule.</li><li>Clear the draft only after the API confirms persistence. Retain its content and retry identity after failure; prevent sending/scheduling it twice in flight. An idempotent retry returning FAILED/CANCELLED retains the draft and directs the user to the queue; SENT is acknowledged as already sent, never as a new schedule.</li><li>A private Scheduled panel shows only the current user&#39;s items in this Workspace, including channel/thread context, due time, status and safe error reason. Support cursor pagination, refresh, time changes and cancel; no native alert/confirm.</li><li>Above the channel/DM composer, show a compact notice when the current user has PENDING/SENDING items in that conversation (including its threads). Show the earliest scheduled time, or an honest waiting/sending state for overdue work, and a one-click action opening the existing private Scheduled panel. Do not show other users&#39; drafts, failed/completed/cancelled items or stale data after errors. Read the next item on the server, independently of the queue&#39;s pagination. Refresh after schedule mutations and periodically while visible. Text uses matching vi/en keys noticeScheduled, noticeWaiting, noticeSending and viewAll under chat.schedule; use existing light/dark tokens and wrap on small screens.</li><li>Scheduling itself creates no chat message, mention notification, unread count or recipient event. Only successful delivery has the usual chat effects.</li><li>Validate sender, channel, mention recipients, thread root and linked context at scheduling and again at delivery. Permission loss, archived/read-only channel, invalid context or missing root must fail safely, without posting. Recheck the sender&#39;s account eligibility using AccountAccessPolicy; a valid Workspace membership never overrides account suspension/deactivation/deletion.</li><li>The server sends while the browser is closed. Recover overdue work after restart; temporary DB/rate-limit failures retry with backoff, at most eight delivery attempts before an actionable FAILED state. Never silently drop an item or label it SENT early.</li><li>Mongo transaction commits the actual message, its notification intent and the SENT transition together. Stable server delivery IDs and the existing unique chat-message index prevent duplicate messages on retry or uncertain commit. A durable broadcastPending intent retries channel events after uncertain commit or broker failure. Realtime events are at-least-once; clients deduplicate by message ID. Replaying an event never inserts another message/notification intent.</li><li>Atomic leases fence workers. Changes/cancel require the expected revision and cannot race an item already SENDING; return a conflict and refresh instead.</li><li>All new text uses parallel vi/en <code>chat.schedule.*</code> keys. Reuse existing semantic colors, dropdown, input, button and responsive side-panel/focus patterns. Support light/dark, keyboard navigation, loading/error/empty/conflict states.</li></ul><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><ul><li>POST <code>/api/v1/workspaces/{ws}/chat/channels/{channel}/scheduled-messages</code>: <code>{message: ChatChannelSendRequest, scheduledAt: ISO8601, timeZone: IANA}</code>. <code>message.clientMessageId</code> is the creation retry key, not the delivery identity.</li><li>GET <code>/api/v1/workspaces/{ws}/chat/scheduled-messages</code>: own items, optional cursor, bounded limit and includeCompleted flag; defaults to PENDING/SENDING/FAILED.</li><li>GET <code>/api/v1/workspaces/{ws}/chat/channels/{channel}/scheduled-messages/upcoming</code>: own earliest PENDING/SENDING item after channel access checks; return only <code>{scheduledAt, timeZone, status}</code>, with null fields when empty. No content/identity data and no new database schema are needed for the conversation notice.</li><li>PATCH <code>.../scheduled-messages/{id}</code>: <code>{revision, scheduledAt, timeZone}</code>.</li><li>DELETE <code>.../scheduled-messages/{id}?revision=...</code>: cancel; preserve audit metadata.</li></ul><p>Structured CHAT_SCHEDULE errors cover missing schema/replica-set support, invalid time, not found/access denied and conflicting revision/state. Only the owner can view/change/cancel a schedule; Manager role does not grant access to others&#39; drafts.</p><h2 id="database-and-rollout" tabindex="-1">Database and rollout <a class="header-anchor" href="#database-and-rollout" aria-label="Permalink to &quot;Database and rollout&quot;">​</a></h2><p>Add only <code>chat_scheduled_messages</code>; preserve existing message data/validators/indexes. MongoDB must support transactions (replica set/Atlas). Add guarded, idempotent Playground-compatible DRY_RUN/APPLY migration and mirror metadata in fresh init. Update ChatSampleSeeder with cancelled-only optional examples, never live scheduled sends. Feature schema readiness is scoped; missing migration must not break normal chat, startup or other modules.</p>',10)])])}const p=a(i,[["render",o]]);export{m as __pageData,p as default};
